---------------------
---- KEYBINDINGS ----
---------------------
hl.bind("SUPER + A", hl.dsp.exec_cmd("kitty"))
hl.bind("SUPER + B", hl.dsp.exec_raw("kitty"))
hl.bind("SUPER + C", hl.dsp.window.close())
hl.bind("SUPER + D", hl.dsp.window.kill())
hl.bind("SUPER + E", hl.dsp.window.close({ window = "class:^(foo)$" }))
hl.bind("SUPER + F", hl.dsp.window.kill({ window = "class:^(foo)$" }))
hl.bind("SUPER + G", hl.dsp.window.signal({ signal = "9" }))
hl.bind("SUPER + H", hl.dsp.window.signal({ window = "class:^(foo)$", signal = "9" }))
hl.bind("SUPER + I", hl.dsp.window.float({ action = "toggle" }))
hl.bind("SUPER + J", hl.dsp.window.float({ action = "set" }))
hl.bind("SUPER + K", hl.dsp.window.float({ action = "unset" }))
hl.bind("SUPER + L", hl.dsp.focus({ workspace = "3" }))
hl.bind("SUPER + M", hl.dsp.workspace.rename({ workspace = "3", name = "code" }))
hl.bind("SUPER + N", hl.dsp.window.fullscreen({ mode = "maximized" }))
hl.bind("SUPER + O", hl.dsp.window.fullscreen_state({ internal = 2, client = 0 }))
hl.bind("SUPER + P", hl.dsp.window.move({ workspace = "4" }))
hl.bind("SUPER + Q", hl.dsp.window.move({ workspace = "special:magic", follow = false }))
hl.bind("SUPER + R", hl.dsp.window.pseudo())
hl.bind("SUPER + S", hl.dsp.focus({ direction = "left" }))
hl.bind("SUPER + T", hl.dsp.window.move({ direction = "right" }))
hl.bind("SUPER + U", hl.dsp.window.swap({ direction = "up" }))
hl.bind("SUPER + V", hl.dsp.window.center())
hl.bind("SUPER + W", hl.dsp.group.toggle())
hl.bind("SUPER + X", hl.dsp.group.next())
hl.bind("SUPER + Y", hl.dsp.group.move_window({ forward = false }))
hl.bind("SUPER + Z", hl.dsp.focus({ monitor = "DP-1" }))
hl.bind("SUPER + F1", hl.dsp.cursor.move_to_corner({ corner = 0 }))
hl.bind("SUPER + F2", hl.dsp.cursor.move({ x = 100, y = 200 }))
hl.bind("SUPER + F3", hl.dsp.exit())
hl.bind("SUPER + F4", hl.dsp.workspace.move({ monitor = "DP-1" }))
hl.bind("SUPER + F5", hl.dsp.focus({ workspace = "2", on_current_monitor = true }))
hl.bind("SUPER + F6", hl.dsp.workspace.move({ workspace = "3", monitor = "DP-1" }))
hl.bind("SUPER + F7", hl.dsp.workspace.toggle_special("magic"))
hl.bind("SUPER + F8", hl.dsp.force_renderer_reload())
hl.bind("SUPER + F9", hl.dsp.window.resize({ x = 10, y = 0, relative = true }))
hl.bind("SUPER + F10", hl.dsp.window.move({ x = 10, y = 0, relative = true }))
hl.bind("SUPER + F11", hl.dsp.window.cycle_next({ next = false, tiled = true }))
hl.bind("SUPER + F12", hl.dsp.focus({ window = "class:^(kitty)$" }))
hl.bind("SUPER + ALT + A", hl.dsp.window.tag({ tag = "code" }))
hl.bind("SUPER + ALT + B", hl.dsp.window.toggle_swallow())
hl.bind("SUPER + ALT + C", hl.dsp.submap("resize"))
hl.bind("SUPER + ALT + D", hl.dsp.pass({ window = "class:^(foo)$" }))
hl.bind("SUPER + ALT + E", hl.dsp.send_shortcut({ mods = "CTRL", key = "C", window = "class:^(foo)$" }))
hl.bind("SUPER + ALT + F", hl.dsp.send_key_state({ mods = "CTRL", key = "C", state = "down", window = "class:^(foo)$" }))
hl.bind("SUPER + ALT + G", hl.dsp.layout("togglesplit"))
hl.bind("SUPER + ALT + H", hl.dsp.dpms({ action = "off", monitor = "DP-1" }))
hl.bind("SUPER + ALT + I", hl.dsp.window.move({ x = 10, y = 20, relative = true, window = "class:^(foo)$" }))
hl.bind("SUPER + ALT + J", hl.dsp.window.resize({ x = 10, y = 20, relative = true, window = "class:^(foo)$" }))
hl.bind("SUPER + ALT + K", hl.dsp.window.swap({ prev = true }))
hl.bind("SUPER + ALT + L", hl.dsp.workspace.swap_monitors({ monitor1 = "DP-1", monitor2 = "DP-2" }))
hl.bind("SUPER + ALT + M", hl.dsp.window.pin())
hl.bind("SUPER + ALT + N", hl.dsp.window.bring_to_top())
hl.bind("SUPER + ALT + O", hl.dsp.window.alter_zorder({ mode = "top", window = "class:^(foo)$" }))
hl.bind("SUPER + ALT + P", hl.dsp.focus({ urgent_or_last = true }))
hl.bind("SUPER + ALT + Q", hl.dsp.focus({ last = true }))
hl.bind("SUPER + ALT + R", hl.dsp.group.lock({ action = "lock" }))
hl.bind("SUPER + ALT + S", hl.dsp.group.lock_active({ action = "toggle" }))
hl.bind("SUPER + ALT + T", hl.dsp.window.move({ into_group = "left" }))
hl.bind("SUPER + ALT + U", hl.dsp.window.move({ into_or_create_group = "right" }))
hl.bind("SUPER + ALT + V", hl.dsp.window.move({ out_of_group = true }))
hl.bind("SUPER + ALT + W", hl.dsp.window.move({ direction = "down" }))
hl.bind("SUPER + ALT + X", hl.dsp.window.deny_from_group({ action = "toggle" }))
hl.bind("SUPER + ALT + Y", hl.dsp.event("myevent"))
hl.bind("SUPER + ALT + Z", hl.dsp.global("myplugin:myglobal"))
hl.bind("SUPER + CTRL + A", hl.dsp.window.set_prop({ window = "class:^(foo)$", prop = "opaque", value = "1" }))
hl.bind("SUPER + CTRL + B", hl.dsp.force_idle())
hl.bind("SUPER + CTRL + C", hl.dsp.release_input_capture())
hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true })
